e'] ?? 'free') === 'paid' ? '/checkout/' : '/student/enroll/' ?>"><input type="hidden" name="csrf_token" value="<?= e((string) $_SESSION['csrf_token']) ?>"><input type="hidden" name="course_id" value="<?= e($courseId) ?>"><button class="learning-course-link" type="submit"><?= $directAccess ? ((string) ($course['accessType'] ?? 'free') === 'free_trial' ? 'Start 7-day free trial' : 'Enroll for free') : ((string) ($course['accessType'] ?? '') === 'paid' ? 'Pay with Mobile Money' : ($courseStatus === 'rejected' ? 'Request a place again' : 'Request a place')) ?> <span aria-hidden="true">&#8594;</span></button></form><?php endif; ?></div></article><?php endforeach; ?></div><?php elseif ($courseQuery !== ''): ?><div class="student-activity-empty"><p>No courses matched that search. Try another course name or topic.</p></div><?php else: ?><div class="student-activity-empty"><p>You’re enrolled in or have requested a place in every course currently listed. Check back for new additions.</p></div><?php endif; ?>
